import json
S='/tmp/claude-0/-home-user-RF-Stuff/0d9de77d-b330-5dee-8336-04e1e971011c/scratchpad/'
P={r['t']:r for r in json.load(open(S+'peer_rows.json'))}
R={r['t']:r for r in json.load(open(S+'reg_data.json'))}
DY={'LIO LN':8.4,'IPX LN':7.5,'JUP LN':3.4,'POLR LN':7.3,'N91 LN':8.3,'PMI LN':15.7,'EMG LN':4.3,'ASHM LN':9.2}
def x(v): return '%.1fx'%v if v is not None and v>0 else 'n.m.'
def peer_rows(order):
    rows=[]
    rows.append(['EV/Sales']+[x(P[t]['evs1']) for t in order])
    rows.append(['EV/EBITDA']+[x(P[t]['eveb']) for t in order])
    rows.append(['EV/EBIT']+[x(P[t]['evebit1']) for t in order])
    rows.append(['P/E']+[x(P[t]['pe1']) for t in order])
    rows.append(['EBITDA margin']+['%.1f%%'%P[t]['ebm'] for t in order])
    rows.append(['EBIT margin']+['%.1f%%'%P[t]['ebitm'] for t in order])
    rows.append(['ND/EBITDA']+['net cash' if P[t]['nd'] is not None and P[t]['nd']<-0.05 else '~0.0x' for t in order])
    rows.append(['Sales growth']+['%+.0f%%'%P[t]['g'] for t in order])
    rows.append(['EV/AUM']+['%.2f%%'%R[t]['evaum'] for t in order])
    rows.append(['Div. yield']+['%.1f%%'%DY[t]+('*' if t=='PMI LN' else '') for t in order])
    return rows
PNOTE='FY+1 consensus (FactSet, 26-Nov-2026) for EV/Sales, EV/EBIT, P/E; EV/EBITDA, margins, ND/EBITDA and sales growth on last reported FY; EV/AUM on latest reported AUM. Yield = FactSet indicated annual dividend / price; *Premier Miton on last declared dividend [u]. Man Group at USD/GBP 1.311.'

